style.css:
@-moz-document domain("bilimclass.kz") {
/* Задаём тёмный фон и светлый текст */
    body {
        background-color: #121212 !important;
        color: #e0e0e0 !important;
    }

    /* Изменяем цвет фона основных блоков */
    div, section, article, header, footer, aside, main, nav {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
    }

    /* Делаем ссылки белыми */
    a {
        color: #ffffff !important;
    }

    a:hover {
        color: #cccccc !important;
    }

    /* Поля ввода и кнопки */
    input, textarea, select, button {
        background-color: #2c2c2c !important;
        color: #ffffff !important;
        border: 1px solid #444 !important;
    }

    /* Дополнительные стили для таблиц */
    table {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
        border-collapse: collapse !important;
    }

    th, td, tr {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
        border: 1px solid #ffffff !important;
    }

    /* Убираем белый фон у всплывающих окон */
    .modal, .popup {
        background-color: #1e1e1e !important;
    }

    /* Дополнительные исправления для элементов с жестко заданным белым фоном */
    [style*="background-color: #ffffff"], 
    [style*="background: white"] {
        background-color: #1e1e1e !important;
        color: #e0e0e0 !important;
    }
}
